import threading

_JWT_CACHE = {}
_JWT_LOCK = threading.RLock()


def build_headers(token, extra=None):
    headers = {"Authorization": "Bearer " + token}
    headers.update(extra or {})
    return headers


def fetch_integration_jwt():
    token = "abc"
    with _JWT_LOCK:
        _JWT_CACHE["jwt"] = token
    return token


def get_cached_jwt():
    with _JWT_LOCK:
        cached = _JWT_CACHE.get("jwt")
    if cached:
        return cached
    return fetch_integration_jwt()


def resolve_auth_header():
    return build_headers(get_cached_jwt())


def jwt_ttl_seconds():
    return 300

